//! Parity of input and outcome transforms in `SingleTaskGP` with BoTorch
//! (fixtures in `tests/fixtures/6b_transforms/*.json`, generated by
//! `scripts/generate_fixtures.py --phase 6b-transforms`).
//!
//! Every fixture describes its transforms as JSON specs (BoTorch class names
//! and keyword arguments, see `botorch_pyo3/tests/transform_helpers.py`),
//! from which this test builds the same [`ChainedInputTransform`] and
//! per-output [`OutcomeChain`]s, and records BoTorch's
//!
//! * parameter names, shapes and optimizer bounds (exact), default raw
//!   parameters (exact) and the training inputs as the model sees them
//!   (1e-9);
//! * MLL values (1e-9, relative) and gradients (1e-8, relative to the largest
//!   component, including learned transform parameters) at the default and
//!   at random raw parameters;
//! * `q = 1` posterior means and variances (the moments of a
//!   `TransformedPosterior`) with and without observation noise, and their
//!   gradients with respect to the inputs (1e-9 / 1e-8); posterior samples
//!   of `q = 3` points from given base samples (1e-9) and the gradient of a
//!   weighted sum of them (1e-8);
//! * `ExpectedImprovement` and `qExpectedImprovement` (given base samples)
//!   values and input gradients (1e-9 / 1e-8);
//! * `fit_gpytorch_mll` from the default parameters, compared with BoTorch's
//!   outcomes on the model and 16 twins (the rule of
//!   `kernels_6a_parity.rs`).
//!
//! Run with `--nocapture` to print the error tables.

mod common;

use std::path::PathBuf;
use std::sync::Arc;

use botorch_core::acquisition::monte_carlo::posterior_samples_with_vjp;
use botorch_core::acquisition::{
    AcquisitionFunction, ExpectedImprovement, McAcquisitionOptions, QExpectedImprovement,
};
use botorch_core::sampling::SobolQMCNormalSampler;
use botorch_core::transforms::input::{
    ChainedInputTransform, InputPerturbation, InputTransformStep, PerturbationSet,
};
use botorch_core::transforms::input_steps::{
    AffineKind, AffineStep, AppendStep, CategoricalEncoder, FeatureSource, FilterStep,
    ImputationStep, Log10Step, NewStep, NumericToCategoricalStep, OneHotEncoder,
    OneHotToNumericStep, RoundStep, TransformFlags, WarpStep,
};
use botorch_core::transforms::outcome::{OutcomeChain, OutcomeStep, StratifiedStandardize};
use botorch_core::{
    fit_gpytorch_mll, BatchedMultiOutputGP, BatchedMultiOutputGPOptions, BotorchError, FitOptions,
    Matrix, Model, Normalize, OutcomeTransformChoice, Prior, Standardize, Vector,
};
use common::{fixture_dir, matrix, Report};
use serde::Deserialize;
use serde_json::Value;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const FIT_TOL: f64 = 1e-6;
const FIT_CLUSTER: f64 = 1e-4;
const CHAOTIC_RANGE: f64 = 1e-3;

#[derive(Deserialize)]
struct Mll {
    value: Vec<f64>,
    grad: Vec<f64>,
}

#[derive(Deserialize)]
struct Fit {
    loss: f64,
    iterations: usize,
    attempts: usize,
    twin_train_x: Vec<Vec<Vec<f64>>>,
    twin_losses: Vec<f64>,
    twin_attempts: Vec<usize>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    input: Value,
    outcome: Value,
    m: usize,
    fixed_noise: bool,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    train_yvar: Option<Vec<Vec<f64>>>,
    #[serde(default)]
    unsupported: bool,
    param_names: Option<Vec<(String, Vec<usize>)>>,
    prefixes: Option<Vec<String>>,
    bounds: Option<Vec<(Value, Value)>>,
    default_raw: Option<Vec<f64>>,
    transformed_train_x: Option<Value>,
    default_mll: Option<Mll>,
    raw: Option<Vec<f64>>,
    mll: Option<Mll>,
    posterior: Option<Value>,
    fit: Option<Fit>,
}

fn num(v: &Value) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().unwrap(),
        Value::String(s) => match s.as_str() {
            "inf" => f64::INFINITY,
            "-inf" => f64::NEG_INFINITY,
            "nan" => f64::NAN,
            other => panic!("not a number: {other}"),
        },
        other => panic!("not a number: {other}"),
    }
}

fn nums(v: &Value) -> Vec<f64> {
    match v {
        Value::Array(a) => a.iter().flat_map(nums).collect(),
        other => vec![num(other)],
    }
}

fn rows(v: &Value) -> Vec<Vec<f64>> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|r| r.as_array().unwrap().iter().map(num).collect())
        .collect()
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as usize)
        .collect()
}

fn prior_of(v: &Value) -> Option<Prior> {
    let p = v.get("__prior__")?;
    let name = p[0].as_str().unwrap();
    let a: Vec<f64> = p[1].as_array().unwrap().iter().map(num).collect();
    let prior = match name {
        "GammaPrior" => Prior::gamma(a[0], a[1]),
        "LogNormalPrior" => Prior::log_normal(a[0], a[1]),
        "NormalPrior" => Prior::normal(a[0], a[1]),
        other => panic!("unknown prior {other}"),
    };
    Some(prior.unwrap().rounded_to_f32())
}

fn flags(s: &Value, default: (bool, bool, bool)) -> TransformFlags {
    match s.get("flags") {
        Some(f) => {
            let f: Vec<bool> = f
                .as_array()
                .unwrap()
                .iter()
                .map(|b| b.as_bool().unwrap())
                .collect();
            TransformFlags {
                train: f[0],
                eval: f[1],
                fantasize: f[2],
            }
        }
        None => TransformFlags {
            train: default.0,
            eval: default.1,
            fantasize: default.2,
        },
    }
}

fn opt_f64(s: &Value, key: &str, default: f64) -> f64 {
    s.get(key).map_or(default, num)
}

fn opt_bool(s: &Value, key: &str) -> bool {
    s.get(key).and_then(Value::as_bool).unwrap_or(false)
}

fn categorical(s: &Value) -> Vec<(usize, usize)> {
    let mut out: Vec<(usize, usize)> = s["categorical_features"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.parse().unwrap(), v.as_u64().unwrap() as usize))
        .collect();
    out.sort_unstable();
    out
}

/// The step of an input transform spec (the plain `Normalize` maps to the
/// original step, as in botorch_rs's Python layer).
fn input_step(s: &Value) -> InputTransformStep {
    let t = s["type"].as_str().unwrap();
    let all = (true, true, true);
    match t {
        "Normalize" => {
            let d = s["d"].as_u64().unwrap() as usize;
            let indices = s.get("indices").map(usizes);
            let center = opt_f64(s, "center", 0.5);
            let reverse = opt_bool(s, "reverse");
            let f = flags(s, all);
            let bounds = s.get("bounds").map(rows);
            let learn = s
                .get("learn_bounds")
                .and_then(Value::as_bool)
                .unwrap_or(bounds.is_none());
            if indices.is_none() && center == 0.5 && !reverse && f == TransformFlags::ALL {
                let n = match &bounds {
                    Some(b) => Normalize::with_bounds(&matrix(b)).unwrap(),
                    None => Normalize::new(d),
                };
                return InputTransformStep::Normalize(n);
            }
            let k = indices.as_ref().map_or(d, Vec::len);
            let (offset, coef) = match &bounds {
                Some(b) => {
                    let cols: Vec<usize> = match &indices {
                        Some(i) if b[0].len() == d => i.clone(),
                        _ => (0..k).collect(),
                    };
                    let coef: Vec<f64> = cols.iter().map(|&j| b[1][j] - b[0][j]).collect();
                    let off: Vec<f64> = cols
                        .iter()
                        .zip(&coef)
                        .map(|(&j, c)| b[0][j] + (0.5 - center) * c)
                        .collect();
                    (off, coef)
                }
                None => (vec![0.0; k], vec![1.0; k]),
            };
            let step = AffineStep::new(
                d,
                indices,
                offset,
                coef,
                AffineKind::Normalize {
                    min_range: opt_f64(s, "min_range", 1e-8),
                    center,
                },
                learn,
            )
            .unwrap()
            .with_reverse(reverse)
            .with_flags(f);
            InputTransformStep::Step(NewStep::Affine(step))
        }
        "InputStandardize" => {
            let d = s["d"].as_u64().unwrap() as usize;
            let indices = s.get("indices").map(usizes);
            let k = indices.as_ref().map_or(d, Vec::len);
            let step = AffineStep::new(
                d,
                indices,
                vec![0.0; k],
                vec![1.0; k],
                AffineKind::Standardize {
                    min_std: opt_f64(s, "min_std", 1e-8),
                },
                true,
            )
            .unwrap()
            .with_reverse(opt_bool(s, "reverse"))
            .with_flags(flags(s, all));
            InputTransformStep::Step(NewStep::Affine(step))
        }
        "AffineInputTransform" => {
            let d = s["d"].as_u64().unwrap() as usize;
            let step = AffineStep::new(
                d,
                s.get("indices").map(usizes),
                nums(&s["offset"]),
                nums(&s["coefficient"]),
                AffineKind::Fixed,
                false,
            )
            .unwrap()
            .with_reverse(opt_bool(s, "reverse"))
            .with_flags(flags(s, all));
            InputTransformStep::Step(NewStep::Affine(step))
        }
        "Warp" => {
            let d = s["d"].as_u64().unwrap() as usize;
            let bounds = s.get("bounds").filter(|b| !b.is_null()).map(|b| {
                let r = rows(b);
                (r[0].clone(), r[1].clone())
            });
            let step = WarpStep::new(d, usizes(&s["indices"]), opt_f64(s, "eps", 1e-7), bounds)
                .unwrap()
                .with_priors(
                    s.get("c0_prior").and_then(prior_of),
                    s.get("c1_prior").and_then(prior_of),
                )
                .with_reverse(opt_bool(s, "reverse"))
                .with_flags(flags(s, all));
            InputTransformStep::Step(NewStep::Warp(step))
        }
        "Round" => {
            let cat = if s.get("categorical_features").is_some_and(|c| !c.is_null()) {
                categorical(s)
            } else {
                Vec::new()
            };
            let step = RoundStep::new(
                s.get("integer_indices").map(usizes).unwrap_or_default(),
                cat,
                opt_bool(s, "approximate"),
                opt_f64(s, "tau", 1e-3),
            )
            .unwrap()
            .with_flags(flags(s, all));
            InputTransformStep::Step(NewStep::Round(step))
        }
        "Log10" => InputTransformStep::Step(NewStep::Log10(
            Log10Step::new(usizes(&s["indices"]))
                .with_reverse(opt_bool(s, "reverse"))
                .with_flags(flags(s, all)),
        )),
        "AppendFeatures" => {
            let step = AppendStep::new(
                FeatureSource::Fixed(matrix(&rows(&s["feature_set"]))),
                opt_bool(s, "skip_expand"),
            )
            .unwrap()
            .with_flags(flags(s, (false, true, false)));
            InputTransformStep::Step(NewStep::Append(step))
        }
        "InteractionFeatures" => InputTransformStep::Step(NewStep::Append(
            AppendStep::interaction(s.get("indices").filter(|i| !i.is_null()).map(usizes)).unwrap(),
        )),
        "FilterFeatures" => InputTransformStep::Step(NewStep::Filter(
            FilterStep::new(usizes(&s["feature_indices"]))
                .unwrap()
                .with_flags(flags(s, all)),
        )),
        "OneHotToNumeric" => InputTransformStep::Step(NewStep::OneHotToNumeric(
            OneHotToNumericStep::new(s["dim"].as_u64().unwrap() as usize, categorical(s))
                .unwrap()
                .with_flags(flags(s, all)),
        )),
        "NumericToCategoricalEncoding" => {
            let cat = categorical(s);
            let enc: Vec<Arc<dyn CategoricalEncoder>> = cat
                .iter()
                .map(|&(_, c)| {
                    Arc::new(OneHotEncoder { num_classes: c }) as Arc<dyn CategoricalEncoder>
                })
                .collect();
            InputTransformStep::Step(NewStep::NumericToCategorical(
                NumericToCategoricalStep::new(s["dim"].as_u64().unwrap() as usize, cat, enc)
                    .unwrap()
                    .with_flags(flags(s, all)),
            ))
        }
        "LearnedFeatureImputation" => {
            let fi: Vec<(i64, Vec<usize>)> = s["feature_indices"]
                .as_object()
                .unwrap()
                .iter()
                .map(|(k, v)| (k.parse().unwrap(), usizes(v)))
                .collect();
            let bounds = s.get("bounds").filter(|b| !b.is_null()).map(|b| {
                let r = rows(b);
                (r[0].clone(), r[1].clone())
            });
            InputTransformStep::Step(NewStep::Imputation(
                ImputationStep::new(
                    fi,
                    s["d"].as_u64().unwrap() as usize,
                    s.get("target_task").and_then(Value::as_i64),
                    bounds,
                )
                .unwrap()
                .with_flags(flags(s, all)),
            ))
        }
        "InputPerturbation" => {
            let f = flags(s, (false, true, false));
            let mut p = InputPerturbation::new(PerturbationSet::Fixed(matrix(&rows(
                &s["perturbation_set"],
            ))))
            .unwrap()
            .with_multiplicative(opt_bool(s, "multiplicative"))
            .with_transform_flags(f.train, f.eval, f.fantasize);
            if let Some(b) = s.get("bounds").filter(|b| !b.is_null()) {
                p = p.with_bounds(matrix(&rows(b))).unwrap();
            }
            if let Some(i) = s.get("indices").filter(|i| !i.is_null()) {
                p = p.with_indices(usizes(i)).unwrap();
            }
            InputTransformStep::Perturbation(p)
        }
        other => panic!("unknown input transform {other}"),
    }
}

fn input_chain(spec: &Value, prefixes: Option<&Vec<String>>) -> Option<ChainedInputTransform> {
    let steps = spec.as_array()?;
    let training: Vec<bool> = steps
        .iter()
        .map(|s| s.get("training").and_then(Value::as_bool).unwrap_or(true))
        .collect();
    let mut chain = ChainedInputTransform::new(steps.iter().map(input_step).collect())
        .unwrap()
        .with_training(training)
        .unwrap();
    if let Some(p) = prefixes {
        chain = chain.with_prefixes(p.clone()).unwrap();
    }
    Some(chain)
}

fn outcome(spec: &Value, m: usize) -> OutcomeTransformChoice {
    match spec {
        Value::Null => OutcomeTransformChoice::None,
        Value::String(s) if s == "default" => OutcomeTransformChoice::Default,
        Value::Array(steps) => OutcomeTransformChoice::Chains(
            (0..m)
                .map(|t| {
                    OutcomeChain::new(
                        steps
                            .iter()
                            .filter(|s| {
                                s.get("outputs")
                                    .filter(|o| !o.is_null())
                                    .is_none_or(|o| usizes(o).contains(&t))
                            })
                            .map(|s| match s["type"].as_str().unwrap() {
                                "Standardize" => OutcomeStep::Standardize(
                                    Standardize::new().with_min_stdv(opt_f64(s, "min_stdv", 1e-8)),
                                ),
                                "Log" => OutcomeStep::Log,
                                "Power" => OutcomeStep::Power(num(&s["power"])),
                                "Bilog" => OutcomeStep::Bilog,
                                "StratifiedStandardize" => OutcomeStep::StratifiedStandardize(
                                    StratifiedStandardize::new(
                                        s["stratification_idx"].as_u64().unwrap() as usize,
                                        &s["task_values"]
                                            .as_array()
                                            .unwrap()
                                            .iter()
                                            .map(|v| v.as_i64().unwrap())
                                            .collect::<Vec<_>>(),
                                        1e-8,
                                    )
                                    .unwrap(),
                                ),
                                other => panic!("unknown outcome transform {other}"),
                            })
                            .collect(),
                    )
                })
                .collect(),
        ),
        other => panic!("bad outcome spec {other}"),
    }
}

fn load() -> Vec<Case> {
    let dir: PathBuf = fixture_dir().join("6b_transforms");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no 6b_transforms fixtures");
    paths
        .iter()
        .map(|p| {
            let text = std::fs::read_to_string(p).unwrap();
            serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
        })
        .collect()
}

fn build(c: &Case, train_x: &[Vec<f64>]) -> botorch_core::Result<BatchedMultiOutputGP> {
    let options = BatchedMultiOutputGPOptions {
        train_yvar: c
            .train_yvar
            .as_ref()
            .filter(|_| c.fixed_noise)
            .map(|v| vec![matrix(v)]),
        outcome_transform: outcome(&c.outcome, c.m),
        input_chain: input_chain(&c.input, c.prefixes.as_ref()),
        ..Default::default()
    };
    BatchedMultiOutputGP::new(
        vec![matrix(train_x)],
        vec![matrix(&c.train_y)],
        Vec::new(),
        options,
    )
}

fn grad_err(a: &[f64], e: &[f64]) -> f64 {
    let scale = e.iter().fold(0.0f64, |m, v| m.max(v.abs())).max(1e-300);
    a.iter()
        .zip(e)
        .map(|(x, y)| (x - y).abs() / scale)
        .fold(0.0, f64::max)
}

fn value_err(a: &[f64], e: &[f64]) -> f64 {
    a.iter()
        .zip(e)
        .map(|(x, y)| {
            if x.is_nan() && y.is_nan() {
                0.0
            } else {
                (x - y).abs() / y.abs().max(1.0)
            }
        })
        .fold(0.0, f64::max)
}

fn check_posterior(
    report: &mut Report,
    name: &str,
    gp: &Arc<BatchedMultiOutputGP>,
    pf: &Value,
    m: usize,
) {
    let model: Arc<dyn Model> = gp.clone();
    if pf.get("x").is_none() {
        return;
    }
    let x = rows(&pf["x"]);
    let d = x[0].len();
    // q = 1 moments and their gradients.
    if let (Some(mean), true) = (pf.get("mean"), gp.points_per_input() > 1) {
        // A one-to-many input transform (m = 1, affine outcome transforms):
        // the marginals of the N points of every input.
        let gp0 = gp.model(0, 0);
        let (mut means, mut vars, mut mn, mut vn, mut dm, mut dv) = (
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        );
        let clamp = |v: f64| v.max(botorch_core::posterior::MIN_VARIANCE);
        for p in &x {
            let row = Matrix::from_row_slice(1, d, p);
            let post = gp0.posterior(&row, false).unwrap();
            let noisy = gp0.posterior(&row, true).unwrap();
            let k = post.mean.len();
            means.extend(post.mean.iter());
            vars.extend(post.covariance.diagonal().iter().map(|&v| clamp(v)));
            mn.extend(noisy.mean.iter());
            vn.extend(noisy.covariance.diagonal().iter().map(|&v| clamp(v)));
            let ones = Vector::from_element(k, 1.0);
            let gm = gp0
                .joint_posterior_vjp(&row, 0..1, &ones, &Matrix::zeros(k, k))
                .unwrap();
            let wv = Matrix::from_fn(k, k, |a, b| {
                f64::from(u8::from(
                    a == b && post.covariance[(a, a)] >= botorch_core::posterior::MIN_VARIANCE,
                ))
            });
            let gv = gp0
                .joint_posterior_vjp(&row, 0..1, &Vector::zeros(k), &wv)
                .unwrap();
            dm.extend(gm.iter());
            dv.extend(gv.iter());
        }
        report.check(name, "q=1 mean", value_err(&means, &nums(mean)), VALUE_TOL);
        report.check(
            name,
            "q=1 variance",
            value_err(&vars, &nums(&pf["variance"])),
            VALUE_TOL,
        );
        report.check(
            name,
            "q=1 d mean / dx",
            grad_err(&dm, &nums(&pf["dmean_dx"])),
            GRAD_TOL,
        );
        report.check(
            name,
            "q=1 d variance / dx",
            grad_err(&dv, &nums(&pf["dvariance_dx"])),
            GRAD_TOL,
        );
        report.check(
            name,
            "q=1 mean (observation noise)",
            value_err(&mn, &nums(&pf["mean_noisy"])),
            VALUE_TOL,
        );
        report.check(
            name,
            "q=1 variance (observation noise)",
            value_err(&vn, &nums(&pf["variance_noisy"])),
            VALUE_TOL,
        );
    } else if let Some(mean) = pf.get("mean") {
        let mut means = Vec::new();
        let mut vars = Vec::new();
        let mut dm = Vec::new();
        let mut dv = Vec::new();
        for p in &x {
            let g = model.point_posterior_with_grad(p).unwrap();
            let transformed = model.transformed_outputs();
            for (t, &tr) in transformed.iter().enumerate().take(m) {
                means.push(g.mean[t]);
                let v = g.covariance[(t, t)];
                let clamped = !tr && v < botorch_core::posterior::MIN_VARIANCE;
                vars.push(if clamped {
                    botorch_core::posterior::MIN_VARIANCE
                } else {
                    v
                });
            }
            for k in 0..d {
                dm.push((0..m).map(|t| g.dmean[k][t]).sum::<f64>());
                dv.push(
                    (0..m)
                        .map(|t| {
                            let clamped = !model.transformed_outputs()[t]
                                && g.covariance[(t, t)] < botorch_core::posterior::MIN_VARIANCE;
                            if clamped {
                                0.0
                            } else {
                                g.dcov[k][(t, t)]
                            }
                        })
                        .sum::<f64>(),
                );
            }
        }
        report.check(name, "q=1 mean", value_err(&means, &nums(mean)), VALUE_TOL);
        report.check(
            name,
            "q=1 variance",
            value_err(&vars, &nums(&pf["variance"])),
            VALUE_TOL,
        );
        report.check(
            name,
            "q=1 d mean / dx",
            grad_err(&dm, &nums(&pf["dmean_dx"])),
            GRAD_TOL,
        );
        report.check(
            name,
            "q=1 d variance / dx",
            grad_err(&dv, &nums(&pf["dvariance_dx"])),
            GRAD_TOL,
        );
        let pp = gp.point_posteriors_at(0, &matrix(&x), true).unwrap();
        let transformed = model.transformed_outputs();
        let mut mn = Vec::new();
        let mut vn = Vec::new();
        for i in 0..x.len() {
            for (t, &tr) in transformed.iter().enumerate() {
                mn.push(pp.mean[(i, t)]);
                let v = pp.variance(i, t);
                vn.push(if !tr && v < botorch_core::posterior::MIN_VARIANCE {
                    botorch_core::posterior::MIN_VARIANCE
                } else {
                    v
                });
            }
        }
        report.check(
            name,
            "q=1 mean (observation noise)",
            value_err(&mn, &nums(&pf["mean_noisy"])),
            VALUE_TOL,
        );
        report.check(
            name,
            "q=1 variance (observation noise)",
            value_err(&vn, &nums(&pf["variance_noisy"])),
            VALUE_TOL,
        );
    }
    // Samples from given base samples.
    let xj = matrix(&rows(&pf["joint_x"]));
    let base = matrix(&rows(&pf["base_samples"]));
    let weights = matrix(&rows(&pf["sample_weights"]));
    let (samples, grad) = posterior_samples_with_vjp(model.as_ref(), &xj, &base, &weights).unwrap();
    let n = samples.num_points();
    let mut sv = Vec::new();
    for s in 0..base.nrows() {
        for p in 0..n {
            for t in 0..m {
                sv.push(samples.value(s, p, t));
            }
        }
    }
    report.check(
        name,
        "samples (given base samples)",
        value_err(&sv, &nums(&pf["samples"])),
        VALUE_TOL,
    );
    report.check(
        name,
        "d (weighted samples) / dx",
        grad_err(&common::matrix_rows(&grad), &nums(&pf["dsamples_dx"])),
        GRAD_TOL,
    );
    // Acquisition functions.
    let best_f = pf.get("best_f").map(num);
    if let (Some(ei), Some(best_f)) = (pf.get("ei"), best_f) {
        let acq = ExpectedImprovement::new(model.clone(), best_f, true).unwrap();
        let xs = rows(&ei["x"]);
        let mut vals = Vec::new();
        let mut grads = Vec::new();
        for p in &xs {
            let (v, g) = acq
                .forward_with_grad(&Matrix::from_row_slice(1, d, p))
                .unwrap();
            vals.push(v);
            grads.extend(common::matrix_rows(&g));
        }
        report.check(
            name,
            "ExpectedImprovement",
            value_err(&vals, &nums(&ei["value"])),
            VALUE_TOL,
        );
        report.check(
            name,
            "ExpectedImprovement d / dx",
            grad_err(&grads, &nums(&ei["grad"])),
            GRAD_TOL,
        );
    }
    if let (Some(qei), Some(best_f)) = (pf.get("qei"), best_f) {
        let base = matrix(&rows(&qei["base_samples"]));
        let sampler = Arc::new(SobolQMCNormalSampler::from_base_samples(base, Some(0)).unwrap());
        let acq = QExpectedImprovement::new(
            model.clone(),
            best_f,
            McAcquisitionOptions {
                sampler: Some(sampler),
                ..Default::default()
            },
        )
        .unwrap();
        let xs: Vec<Vec<Vec<f64>>> = qei["x"].as_array().unwrap().iter().map(rows).collect();
        let mut vals = Vec::new();
        let mut grads = Vec::new();
        for xq in &xs {
            let (v, g) = acq.forward_with_grad(&matrix(xq)).unwrap();
            vals.push(v);
            grads.extend(common::matrix_rows(&g));
        }
        report.check(
            name,
            "qExpectedImprovement",
            value_err(&vals, &nums(&qei["value"])),
            VALUE_TOL,
        );
        report.check(
            name,
            "qExpectedImprovement d / dx",
            grad_err(&grads, &nums(&qei["grad"])),
            GRAD_TOL,
        );
    }
}

#[test]
fn transforms_match_botorch() {
    let mut report = Report::default();
    for c in load() {
        let name = c.name.as_str();
        if c.unsupported {
            let r = build(&c, &c.train_x);
            report.check(
                name,
                "unsupported configuration rejected",
                f64::from(u8::from(!matches!(r, Err(BotorchError::Unsupported(_))))),
                0.0,
            );
            continue;
        }
        let mut gp = build(&c, &c.train_x).unwrap_or_else(|e| panic!("{name}: {e}"));
        // Names, shapes, bounds and default raw parameters.
        let shapes = gp.parameter_shapes();
        let expected = c.param_names.as_ref().unwrap();
        report.check(
            name,
            "parameter names and shapes",
            f64::from(u8::from(&shapes != expected)),
            0.0,
        );
        if &shapes != expected {
            println!("{name}: {shapes:?} vs {expected:?}");
        }
        let bounds = gp.raw_parameter_bounds();
        let eb: Vec<(f64, f64)> = c
            .bounds
            .as_ref()
            .unwrap()
            .iter()
            .map(|(a, b)| (num(a), num(b)))
            .collect();
        report.check(
            name,
            "optimizer bounds",
            f64::from(u8::from(bounds != eb)),
            0.0,
        );
        let default_raw = c.default_raw.as_ref().unwrap();
        report.check(
            name,
            "default raw parameters",
            value_err(gp.raw_parameters().as_slice(), default_raw),
            0.0,
        );
        // The training inputs as the model sees them.
        // (Batched over the outputs if m > 1, as in BoTorch.)
        let x_tf: Vec<f64> = (0..c.m)
            .flat_map(|t| common::matrix_rows(gp.model(0, t).transformed_train_inputs()))
            .collect();
        report.check(
            name,
            "transformed training inputs",
            value_err(&x_tf, &nums(c.transformed_train_x.as_ref().unwrap())),
            VALUE_TOL,
        );
        // MLLs.
        let (v, g) = gp.mll_values_and_grad(default_raw).unwrap();
        let dm = c.default_mll.as_ref().unwrap();
        report.check(name, "default MLL", value_err(&v, &dm.value), VALUE_TOL);
        report.check(
            name,
            "default MLL gradient",
            grad_err(g.as_slice(), &dm.grad),
            GRAD_TOL,
        );
        let raw = c.raw.as_ref().unwrap();
        let (v, g) = gp.mll_values_and_grad(raw).unwrap();
        let mm = c.mll.as_ref().unwrap();
        report.check(name, "MLL", value_err(&v, &mm.value), VALUE_TOL);
        report.check(
            name,
            "MLL gradient",
            grad_err(g.as_slice(), &mm.grad),
            GRAD_TOL,
        );
        // Posteriors and acquisition functions at the random parameters.
        gp.set_raw_parameters(raw).unwrap();
        let gp = Arc::new(gp);
        if let Some(pf) = &c.posterior {
            check_posterior(&mut report, name, &gp, pf, c.m);
        }
        // Fits from the default parameters.
        if let Some(f) = &c.fit {
            let mut fitted = build(&c, &c.train_x).unwrap();
            fitted.set_raw_parameters(default_raw).unwrap();
            let r = fit_gpytorch_mll(&mut fitted, FitOptions::default()).unwrap();
            let bt: Vec<f64> = std::iter::once((f.loss, f.attempts))
                .chain(
                    f.twin_losses
                        .iter()
                        .copied()
                        .zip(f.twin_attempts.iter().copied()),
                )
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let own_attempts = r.results[0].attempts;
            let rs: Vec<f64> = std::iter::once((r.loss, own_attempts))
                .chain(f.twin_train_x.iter().map(|x| {
                    let mut twin = build(&c, x).unwrap();
                    twin.set_raw_parameters(default_raw).unwrap();
                    let t = fit_gpytorch_mll(&mut twin, FitOptions::default()).unwrap();
                    (t.loss, t.results[0].attempts)
                }))
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let (n_bt, n_rs) = (f.twin_losses.len() + 1, f.twin_train_x.len() + 1);
            common::compare_first_attempt_failures(
                &mut report,
                name,
                "fit",
                (n_bt - bt.len(), n_bt),
                (n_rs - rs.len(), n_rs),
            );
            let bt_best = bt.iter().copied().fold(f64::INFINITY, f64::min);
            let bt_worst = bt.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            let rs_best = rs.iter().copied().fold(f64::INFINITY, f64::min);
            let spread = bt
                .iter()
                .copied()
                .filter(|&l| l <= bt_best + FIT_CLUSTER)
                .fold(bt_best, f64::max)
                - bt_best;
            let tol = FIT_TOL.max(10.0 * spread);
            if bt_worst - bt_best > CHAOTIC_RANGE {
                common::compare_chaotic_fits(&mut report, name, "fit", &bt, &rs, FIT_TOL);
            } else {
                report.check(
                    name,
                    "fit: best loss above BoTorch's best (scaled)",
                    (rs_best - bt_best).max(0.0) / tol,
                    1.0,
                );
                if own_attempts == 1 {
                    report.check(
                        name,
                        "fit: loss above BoTorch's worst (scaled)",
                        (r.loss - bt_worst).max(0.0) / tol,
                        1.0,
                    );
                }
            }
            println!(
                "{name:26} fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), \
                 first-attempt outcomes: BoTorch [{bt_best:+.10}, {bt_worst:+.10}] ({} of {}), \
                 botorch_rs best {rs_best:+.10} ({} of {}), spread {spread:.1e}",
                r.loss,
                f.loss,
                r.results[0].iterations,
                f.iterations,
                bt.len(),
                f.twin_losses.len() + 1,
                rs.len(),
                f.twin_losses.len() + 1
            );
        }
    }
    report.finish("6b transforms: input and outcome transforms in SingleTaskGP");
}

#[test]
fn outcome_chains_without_moments_raise_not_implemented() {
    // `Power` and `Bilog` have no mean transform: BoTorch's
    // NotImplementedError("No mean transform provided.").
    let x = Matrix::from_fn(6, 1, |i, _| i as f64 / 6.0);
    let y = x.map(|v| 1.0 + v * v);
    let gp = BatchedMultiOutputGP::multi_output(
        x,
        y,
        botorch_core::SingleTaskGPOptions {
            outcome_transform: OutcomeTransformChoice::Chains(vec![OutcomeChain::new(vec![
                OutcomeStep::Power(2.0),
            ])]),
            ..Default::default()
        },
    )
    .unwrap();
    let e = Model::posterior_marginals(&gp, &Matrix::from_element(1, 1, 0.3)).unwrap_err();
    assert!(e.to_string().contains("No mean transform provided."), "{e}");
    assert_eq!(Model::transformed_outputs(&gp), vec![true]);
}

#[test]
fn nan_samples_give_nan_acquisition_values_as_in_botorch() {
    // `Power(2)` untransforms samples by `s^(1/2)`, which is NaN at negative
    // base samples; torch's reductions propagate the NaN to the value and
    // every gradient entry of the t-batch.
    let x = Matrix::from_fn(6, 1, |i, _| i as f64 / 6.0);
    let y = x.map(|v| 0.2 + 0.1 * v);
    let gp: Arc<dyn Model> = Arc::new(
        BatchedMultiOutputGP::multi_output(
            x,
            y,
            botorch_core::SingleTaskGPOptions {
                outcome_transform: OutcomeTransformChoice::Chains(vec![OutcomeChain::new(vec![
                    OutcomeStep::Power(2.0),
                ])]),
                ..Default::default()
            },
        )
        .unwrap(),
    );
    let qei = |z: f64| {
        let sampler = Arc::new(
            SobolQMCNormalSampler::from_base_samples(Matrix::from_element(4, 1, z), Some(0))
                .unwrap(),
        );
        QExpectedImprovement::new(
            gp.clone(),
            0.0,
            McAcquisitionOptions {
                sampler: Some(sampler),
                ..Default::default()
            },
        )
        .unwrap()
        .forward_with_grad(&Matrix::from_element(1, 1, 0.45))
        .unwrap()
    };
    let (v, g) = qei(-40.0);
    assert!(v.is_nan() && g.iter().all(|x| x.is_nan()), "{v} {g}");
    let (v, g) = qei(0.0);
    assert!(v.is_finite() && g.iter().all(|x| x.is_finite()), "{v} {g}");
}
